import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2022Q3 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2022Q3 Ceph社区季度进展报告","date":"2022-09-01T00:00:00.000Z","updated":"2022-09-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/2022Q3_Ceph社区季度总结.md","filePath":"posts/2022/2022Q3_Ceph社区季度总结.md","lastUpdated":1780460162000}'),i={name:"posts/2022/2022Q3_Ceph社区季度总结.md"};function h(s,e,l,n,_,m){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="ceph-社区-2022q3-季度进展报告" tabindex="-1">Ceph 社区 2022Q3 季度进展报告 <a class="header-anchor" href="#ceph-社区-2022q3-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2022Q3 季度进展报告&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区的讨论集中在以下几个核心方向：</p><p><strong>Crimson/SeaStore 新一代存储引擎</strong> 多核架构（multi-core）推进是本季度最持续的议题，贯穿整个季度的 Crimson/SeaStore 会议。ZNS（Zone Namespace）设备支持、垃圾回收（GC）优化、对象存储改进均有实质性进展。详见 <a href="/VideoSummary/posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-07-06.html">Ceph_Crimson_SeaStore_Meeting_2022-07-06</a>) 和 <a href="/VideoSummary/posts/2022/Crimson_SeaStore_Meeting_2022-07-13.html">Crimson_SeaStore_Meeting_2022-07-13</a>)。</p><p><strong>BlueStore 性能优化</strong> 共享 Blob 的性能问题、RocksDB 写放大、Tombstone 行为优化是 Performance Meeting 的核心议题，持续讨论了整个季度。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-09-15.html">Ceph_Performance_Meeting_2022-09-15</a>) 和 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-07-28.html">Ceph_Performance_Meeting_2022-07-28</a>)。</p><p><strong>Orchestrator 与部署管理</strong> NFS HA 部署、RGW Multi-Site 配置自动化、cephadm 二进制分发是 Orchestrator 会议的主线。</p><p><strong>RGW 模块化与性能计数器</strong> RGW 模块化进程和性能指标管理的可扩展性问题在季度末集中讨论。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="crimson-seastore" tabindex="-1">Crimson/SeaStore <a class="header-anchor" href="#crimson-seastore" aria-label="Permalink to &quot;Crimson/SeaStore&quot;">​</a></h3><ul><li><strong>ZNS 驱动开发</strong>：Aravind 提交了 ZNS 驱动的多个补丁，解决了 Zone 关闭后磁盘无法重新打开的问题，并修改 ZNS 管理器在写入时填充空间以避免容量浪费。详见 <a href="/VideoSummary/posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-07-06.html">Ceph_Crimson_SeaStore_Meeting_2022-07-06</a>)。</li><li><strong>多核分支推进</strong>：第二个多核 PR 在 7 月中旬完成，第三个随即启动。iOS 相关功能在 9 月完成。详见 <a href="/VideoSummary/posts/2022/Crimson_SeaStore_Meeting_2022-07-13.html">Crimson_SeaStore_Meeting_2022-07-13</a>)。</li><li><strong>SMR 硬盘支持探索</strong>：提出为 SMR（叠瓦式磁记录）硬盘创建专用段管理器（Segment Manager）的方向。</li><li><strong>GC 优化</strong>：Jinyu 提出在 GC 事务中增加判断逻辑，避免将不满足时间局部性原则的 extent 加入 Aerial，减少无效 GC 开销。</li><li><strong>omap 范围移除优化</strong>：9 月会议讨论了存储节点负载、内存拷贝效率和树状结构平衡的改进。详见 <a href="/VideoSummary/posts/2022/Ceph_Crimson_Seastore_Meeting_2022-09-23.html">Ceph_Crimson_Seastore_Meeting_2022-09-23</a>)。</li></ul><h3 id="bluestore-rocksdb" tabindex="-1">BlueStore / RocksDB <a class="header-anchor" href="#bluestore-rocksdb" aria-label="Permalink to &quot;BlueStore / RocksDB&quot;">​</a></h3><ul><li><strong>共享 Blob 重构</strong>：Adam 提出单一实例跟踪器（single instance tracker）方案，通过统一管理所有对象分配来减少共享 Blob 实例数量，实测显著降低 CPU 使用率和写入负载。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-09-22.html">Ceph_Performance_Meeting_2022-09-22</a>)。</li><li><strong>RocksDB 写放大优化</strong>：开发了按列族（column family）跟踪删除操作、达到阈值后手动触发 compaction 和 flush 的机制，以改善 Tombstone 行为。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-07-28.html">Ceph_Performance_Meeting_2022-07-28</a>)。</li><li><strong>BlueStore Zero Block Detection</strong>：分析了该特性在 Quincy 17.2.1 中被默认关闭后导致的性能回退问题，Laura 与 DFG 存储团队跟进 17.2.0 与 17.2.1 的性能差异。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-07-14.html">Ceph_Performance_Meeting_2022-07-14</a>)。</li><li><strong>Snap Map 性能</strong>：讨论了频繁创建快照导致 RBD 镜像性能下降的问题，计划设计专项测试验证。</li></ul><h3 id="orchestrator-cephadm" tabindex="-1">Orchestrator / cephadm <a class="header-anchor" href="#orchestrator-cephadm" aria-label="Permalink to &quot;Orchestrator / cephadm&quot;">​</a></h3><ul><li><strong>NFS HA 部署</strong>：Adam 提交了通过虚拟 IP 地址启动 NFS 守护进程的 PR，并与 Manila 团队协调故障转移场景测试。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_2022-08-09.html">Ceph_Orchestrator_2022-08-09</a>)。</li><li><strong>RGW Multi-Site 配置自动化</strong>：Sebastian 提出在 cephadm 中引入 <code>kind</code> 关键字层级结构，统一 <code>rgw_spec</code> 等规范类，实现多站点配置的原子化部署（全成功或回滚）。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-08-16.html">Ceph_Orchestrator_Meeting_2022-08-16</a>)。</li><li><strong>网络过滤（fb filtering）优化</strong>：放宽子网匹配规则，引入 Python <code>ipaddress</code> 库进行子网匹配检查。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-07-12.html">Ceph_Orchestrator_Meeting_2022-07-12</a>)。</li><li><strong>日志级别配置</strong>：讨论了为 cephadm 二进制程序提供可配置日志级别的方案，以减少默认 debug 级别产生的冗余日志。</li></ul><h3 id="rgw" tabindex="-1">RGW <a class="header-anchor" href="#rgw" aria-label="Permalink to &quot;RGW&quot;">​</a></h3><ul><li><strong>性能计数器管理</strong>：讨论了标签化性能计数器（labeled perf counters）的可扩展性问题，提出&quot;热用户/热存储桶&quot;自动化策略，动态启用相关计数器，避免 Prometheus 端指标爆炸。详见 <a href="/VideoSummary/posts/2022/RGW_Refactoring_Meeting_2022-09-28.html">RGW_Refactoring_Meeting_2022-09-28</a>)。</li><li><strong>HTTP/3 前端原型</strong>：Ronan 提到 RGW HTTP/3 前端的开发进展，开放社区成员参与测试。</li></ul><h3 id="测试基础设施" tabindex="-1">测试基础设施 <a class="header-anchor" href="#测试基础设施" aria-label="Permalink to &quot;测试基础设施&quot;">​</a></h3><ul><li><strong>Teuthology 错误检测改进</strong>：实习生项目实现了自动扫描日志文件、精确记录单元测试失败信息的功能，替代原有的模糊错误码，以可选方式集成。详见 <a href="/VideoSummary/posts/2022/Ceph_Tech_Talk_-_Making_Teuthology_a_Better_Detective.html">Ceph_Tech_Talk_-_Making_Teuthology_a_Better_Detective</a>)。</li><li><strong>测试矩阵动态控制</strong>：Patrick 的PR 通过脚本动态控制测试矩阵中的片段合并，提高测试灵活性，已合并。详见 <a href="/VideoSummary/posts/2022/Ceph_Developer_Monthly_2022-08-03.html">Ceph_Developer_Monthly_2022-08-03</a>)。</li></ul><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><ul><li><strong>Ceph 发布流程现代化</strong>：签名机器从 OCTA 实验室迁移至 sepia 实验室，GPG 密钥转移至硬件安全令牌（HSM），允许非 Red Hat 成员参与发布流程，降低社区贡献门槛。详见 <a href="/VideoSummary/posts/2022/Walkthrough_-_Ceph_Release_Process.html">Walkthrough_-_Ceph_Release_Process</a>)。</li><li><strong>Reef 分支准备</strong>：更新 chakra 节点并重新部署 shock，为 Reef 主版本发布做基础设施准备。</li><li><strong>cephadm 二进制分发</strong>：确认 daily build 和 RPM 包可用，推进解决签名问题，通过社区邮件寻求协助。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-09-27.html">Ceph_Orchestrator_Meeting_2022-09-27</a>)。</li><li><strong>管理标签（admin label）机制</strong>：确定使用哈希文件管理 <code>ceph.conf</code> 和 admin keyring 的部署与移除，避免误删非 cephadm 管理的文件。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_2022-07-26.html">Ceph_Orchestrator_2022-07-26</a>)。</li><li><strong>性能计数器允许列表（allowlist）</strong>：决定开发 PoC 验证通过允许列表控制哪些性能计数器上报给 Manager，以减少 Manager 负载。详见 <a href="/VideoSummary/posts/2022/Ceph_Developer_Monthly_2022-08-03.html">Ceph_Developer_Monthly_2022-08-03</a>)。</li><li><strong>PG Log Dupe Ops内存问题修复</strong>：确定在 OSD 重启时分批修剪（每次 10,000 条）损坏 Dupe 条目的方案，防止无限积累。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-07-14.html">Ceph_Performance_Meeting_2022-07-14</a>)。</li></ul><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><ul><li><strong>Grace Hopper Open Source Day 准备</strong>：社区成员被鼓励标记或新建 &quot;good first issue&quot;，为即将到来的 Grace Hopper 活动吸引新贡献者。详见 <a href="/VideoSummary/posts/2022/Ceph_Developer_Monthly_2022-08-03.html">Ceph_Developer_Monthly_2022-08-03</a>)。</li><li><strong>实习生项目</strong>：本季度有实习生参与 Teuthology 改进项目，并在 Ceph Tech Talk 上公开展示成果，体现了社区对新贡献者的培养。详见 <a href="/VideoSummary/posts/2022/Ceph_Tech_Talk_-_Making_Teuthology_a_Better_Detective.html">Ceph_Tech_Talk_-_Making_Teuthology_a_Better_Detective</a>)。</li><li><strong>Orchestrator 测试覆盖率专项</strong>：9 月会议专门讨论了 <code>video.py</code> 等文件的测试覆盖率提升计划，通过 Etherpad 协作分工，推动测试质量改善。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-09-20.html">Ceph_Orchestrator_Meeting_2022-09-20</a>)。</li><li><strong>会议记录归档</strong>：讨论了对长期项目会议记录进行定期归档的必要性，以保持文档可管理性。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_2022-07-26.html">Ceph_Orchestrator_2022-07-26</a>)。</li><li><strong>跨团队协作</strong>：Orchestrator 团队与 OpenStack Manila 团队就 NFS 故障转移测试建立了定期协作机制；Performance 团队与 DFG 存储团队联合排查 BlueStore 性能回退问题。</li></ul><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度的讨论方向，预计 2022Q4 将重点推进以下工作：</p><ol><li><strong>Crimson/SeaStore 多核稳定化</strong>：多核分支的后续 PR 将陆续提交，ZNS 设备上的 GC 问题需要持续调试，HDD 和 SMR 硬盘支持方案将进入设计阶段。</li><li><strong>BlueStore 共享 Blob 重构落地</strong>：Adam 的单一实例跟踪器方案和 Mark 的碎片整理方案将进入性能测试和代码审查阶段，预计对 RBD 快照密集场景有显著改善。</li><li><strong>RGW Multi-Site 自动化部署</strong>：Sebastian 的 <code>kind</code> 关键字方案将进入后端实现阶段，前端展示方式待后端完成后确定。</li><li><strong>Reef 发布准备</strong>：基础设施迁移和 cephadm 二进制签名问题的解决将为 Reef 版本发布铺路。</li><li><strong>性能计数器架构改进</strong>：RGW 标签化计数器工具和 Manager 允许列表 PoC 将进入验证阶段，长期可能需要构建动态启停计数器的新机制。</li><li><strong>测试基础设施持续改善</strong>：Teuthology 错误检测功能将扩展到更多测试类型，Orchestrator 测试覆盖率专项将持续推进。</li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-07-06.html">Ceph Crimson/SeaStore Meeting 2022-07-06</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Crimson_Seastore_Meeting_2022-09-23.html">Ceph Crimson/Seastore Meeting 2022-09-23</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Developer_Monthly_2022-08-03.html">Ceph Developer Monthly 2022-08-03</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_2022-07-26.html">Ceph Orchestrator 2022-07-26</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_2022-08-09.html">Ceph Orchestrator 2022-08-09</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-07-05.html">Ceph Orchestrator Meeting 2022-07-05</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-07-12.html">Ceph Orchestrator Meeting 2022-07-12</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-08-16.html">Ceph Orchestrator Meeting 2022-08-16</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-09-20.html">Ceph Orchestrator Meeting 2022-09-20</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-09-27.html">Ceph Orchestrator Meeting 2022-09-27</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-07-14.html">Ceph Performance Meeting 2022-07-14</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-07-28.html">Ceph Performance Meeting 2022-07-28</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-08-04.html">Ceph Performance Meeting 2022-08-04</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-09-15.html">Ceph Performance Meeting 2022-09-15</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-09-22.html">Ceph Performance Meeting 2022-09-22</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Tech_Talk_-_Making_Teuthology_a_Better_Detective.html">Ceph Tech Talk: Making Teuthology a Better Detective</a>)</li><li><a href="/VideoSummary/posts/2022/Crimson_SeaStore_Meeting_2022-07-13.html">Crimson/SeaStore Meeting 2022-07-13</a>)</li><li><a href="/VideoSummary/posts/2022/RGW_Refactoring_Meeting_2022-09-28.html">RGW Refactoring Meeting 2022-09-28</a>)</li><li><a href="/VideoSummary/posts/2022/Walkthrough_-_Ceph_Release_Process.html">Walkthrough- Ceph Release Process</a>)</li></ul>',33)])])}const c=r(i,[["render",h]]);export{g as __pageData,c as default};
